import{$ as e,At as t,H as n,_t as r,at as i,nt as a,rt as o,xt as s}from"./chunks/framework.ByJSXnli.js";var c=JSON.parse(`{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}`),l={name:`guide/index.md`};function u(n,c,l,u,d,f){let p=s(`ModelDiagram`);return r(),a(`div`,null,[c[1]||=o(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><p>HeuristicLib is a .NET library for building, running and studying heuristic optimization algorithms. It offers ready algorithms for common searches and typed building blocks for custom ones.</p><p>Use it when the answer is one of many candidates and checking a candidate is easier than deriving the best one. Typical tasks are scheduling, routing, parameter tuning and symbolic regression.</p><h2 id="the-model-in-one-sentence" tabindex="-1">The model in one sentence <a class="header-anchor" href="#the-model-in-one-sentence" aria-label="Permalink to “The model in one sentence”">​</a></h2><p>An <strong>algorithm</strong> uses <strong>operators</strong> to explore the <strong>search space</strong> of a <strong>problem</strong> and yields <strong>search states</strong> that show its progress.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Concept</th><th>Question it answers</th><th>Example</th></tr></thead><tbody><tr><td>Candidate</td><td>What does one possible answer look like?</td><td>A vector of four real numbers</td></tr><tr><td>Search space</td><td>Which candidates are valid?</td><td>Four values between <code>-5.12</code> and <code>5.12</code></td></tr><tr><td>Problem</td><td>How is a candidate evaluated?</td><td>Calculate the Rastrigin function</td></tr><tr><td>Objective</td><td>Which result is better?</td><td>A smaller function value</td></tr><tr><td>Algorithm and operators</td><td>How do we explore?</td><td>Genetic algorithm with crossover and mutation</td></tr><tr><td>Search state</td><td>What has happened so far?</td><td>Population and objective values after generation 12</td></tr></tbody></table></div>`,6),i(p,null,{default:t(()=>[...c[0]||=[e(`p`,null,`The parts stay separate. Compare algorithms on one problem, swap a mutation operator or repeat a configuration with other seeds. Each call starts a fresh run.`,-1)]]),_:1}),c[2]||=o(`<h2 id="configurations-and-executors" tabindex="-1">Configurations and executors <a class="header-anchor" href="#configurations-and-executors" aria-label="Permalink to “Configurations and executors”">​</a></h2><p>The library works in two layers.</p><p>A <strong>configuration</strong> is immutable data that describes an algorithm and its operators. It holds settings such as a population size and child configurations such as the mutator of a genetic algorithm. It holds no executor and no result, so you can copy and reuse it freely. Changing a setting creates a modified copy. A configuration of plain settings, such as a <code>GaussianMutator</code>, compares by value and can be stored as data. A <code>Counter</code> compares by reference, and a configuration that holds a delegate cannot be persisted.</p><p>An <strong>executor</strong> is built from a configuration for one run and holds all runtime state, such as counters and caches. The library builds executors for you, and each run builds its own. No library state carries over between runs. State that your own delegate captures is yours to manage.</p><p>A <strong>run</strong> owns one execution, its executors and its <strong>run results</strong>, such as an analyzer&#39;s trace or a counter&#39;s count.</p><p><a href="/guide/fundamentals/configurations.html">Configurations</a> explains how to read, rewrite and share the configuration graph that an algorithm forms with its operators.</p><h2 id="the-parts-of-a-run" tabindex="-1">The parts of a run <a class="header-anchor" href="#the-parts-of-a-run" aria-label="Permalink to “The parts of a run”">​</a></h2><h3 id="candidate-and-search-space" tabindex="-1">Candidate and search space <a class="header-anchor" href="#candidate-and-search-space" aria-label="Permalink to “Candidate and search space”">​</a></h3><p>A candidate is one proposed solution. Its type represents the shape of the answer, such as <code>RealVector</code>, <code>IntegerVector</code>, <code>BoolVector</code> or <code>Permutation</code>.</p><p>The search space owns validity rules for that type. A <code>BoundedRealVectorSearchSpace</code> can specify length and bounds. Operators use that information when creating or modifying candidates. Read <a href="/guide/fundamentals/search-spaces.html">Search spaces</a> for the built-in choices.</p><h3 id="problem-and-objective" tabindex="-1">Problem and objective <a class="header-anchor" href="#problem-and-objective" aria-label="Permalink to “Problem and objective”">​</a></h3><p>A problem combines the search space, the evaluation of a candidate and the objective.</p><p>Evaluation produces an objective vector, even for a single objective. The objective says whether lower or higher values are better and how results compare. Read <a href="/guide/fundamentals/problems.html">Problems</a> and <a href="/guide/fundamentals/objectives.html">Objectives and candidates</a>.</p><h3 id="algorithm-and-operators" tabindex="-1">Algorithm and operators <a class="header-anchor" href="#algorithm-and-operators" aria-label="Permalink to “Algorithm and operators”">​</a></h3><p>An algorithm owns the search process and its stopping budget. Operators perform focused steps within that process. A genetic algorithm usually needs operators to create candidates, select parents, cross parents and mutate offspring.</p><p>So you can change the variation without writing another generation loop. Type parameters and validation catch incompatible combinations before a run. Read <a href="/guide/fundamentals/algorithms.html">Algorithms</a> and <a href="/guide/fundamentals/operators.html">Operators</a>.</p><h3 id="search-states" tabindex="-1">Search states <a class="header-anchor" href="#search-states" aria-label="Permalink to “Search states”">​</a></h3><p>Algorithms yield immutable snapshots of useful progress. A population based state contains evaluated candidates. Iteration counts come from observations or counters rather than from the state.</p><p>You can consume every state for progress reporting and analysis or ask only for the final state. Read <a href="/guide/execution/search-states.html">Search states</a> and <a href="/guide/execution/running-algorithms.html">Algorithm runs</a>.</p><h3 id="randomness-is-an-input" tabindex="-1">Randomness is an input <a class="header-anchor" href="#randomness-is-an-input" aria-label="Permalink to “Randomness is an input”">​</a></h3><p>Stochastic algorithms receive an explicit random number generator. A recorded seed is part of an experiment configuration, just like the population size or mutation rate. It makes a surprising run reproducible. Read <a href="/guide/execution/randomness.html">Reproducible randomness</a>.</p><h2 id="important-guarantees" tabindex="-1">Important guarantees <a class="header-anchor" href="#important-guarantees" aria-label="Permalink to “Important guarantees”">​</a></h2><ul><li>Search spaces define candidate validity.</li><li>Problems own evaluation and objective semantics.</li><li>Evaluated candidates keep a candidate together with its objective vector.</li><li>A configuration never changes. State the library creates for a run lives in the executors and run results of that run.</li><li>Each call to <code>RunStreaming</code> or <code>RunToCompletionAsync</code> starts a fresh run.</li><li>The same configuration and seed are intended to produce the same stochastic sequence.</li><li>One run is evidence, not a reliable comparison of stochastic algorithms.</li></ul><h2 id="what-is-included" tabindex="-1">What is included <a class="header-anchor" href="#what-is-included" aria-label="Permalink to “What is included”">​</a></h2><ul><li>Population based algorithms including genetic algorithms, evolution strategies and NSGA-II</li><li>Local search algorithms including hill climbing</li><li>Search spaces for real, integer, Boolean and permutation vectors</li><li>Reusable creation, crossover, mutation and selection operators</li><li>Single objective and multiobjective evaluation</li><li>Repeatable experiments, parameter grids and analysis helpers</li><li>Specialized support for machine learning, symbolic regression and symbolic expressions</li><li>Source based Python integration through pythonnet</li></ul><p>HeuristicLib targets .NET 10. The package is currently prerelease software, so expect APIs to evolve between versions.</p><h2 id="choose-your-path" tabindex="-1">Choose your path <a class="header-anchor" href="#choose-your-path" aria-label="Permalink to “Choose your path”">​</a></h2><p>For ordinary use, configure an algorithm and call <code>RunToCompletion</code> or <code>RunToCompletionAsync</code> with a problem and a random source. Start with <a href="/guide/getting-started.html">Build your first optimizer</a>.</p><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Your goal</th><th>Start here</th><th>Learn when needed</th></tr></thead><tbody><tr><td>Practitioner: solve a problem with existing components</td><td><a href="/guide/getting-started.html">First optimizer</a> and <a href="/guide/fundamentals/algorithms.html">Algorithms</a></td><td>Compatible operators and stopping budgets</td></tr><tr><td>Experimenter: compose and compare configurations</td><td><a href="/guide/fundamentals/configurations.html">Configurations</a>, <a href="/guide/fundamentals/operator-composition.html">Operator composition</a> and <a href="/guide/execution/experiments.html">Experiments</a></td><td>Repetitions, parameter grids and trial analysis</td></tr><tr><td>Analysis: measure progress or compare runs</td><td><a href="/guide/execution/observability-and-analysis.html">Analysis of algorithm runs</a> and <a href="/guide/execution/experiments.html">Experiments</a></td><td>Quality curves, operator measurements and trial comparisons</td></tr><tr><td>Integrator: control execution in an application</td><td><a href="/guide/execution/running-algorithms.html">Algorithm runs</a></td><td>Streaming, cancellation and explicit runs</td></tr><tr><td>Component author: add a problem, operator or algorithm</td><td><a href="/guide/fundamentals/problems.html">Problems</a> and <a href="/extend/">Extend HeuristicLib</a></td><td>The authoring contract for that component</td></tr></tbody></table></div><p>Custom components run through the same entry points as built-in ones.</p><h2 id="a-typical-workflow" tabindex="-1">A typical workflow <a class="header-anchor" href="#a-typical-workflow" aria-label="Permalink to “A typical workflow”">​</a></h2><ol><li>Describe valid candidates with a search space.</li><li>Define how the problem evaluates a candidate.</li><li>Choose an algorithm and compatible operators.</li><li>Run with an explicit random seed.</li><li>Inspect the final result or stream intermediate states.</li><li>Repeat runs to compare configurations rather than trusting one stochastic result.</li></ol><p><a href="/guide/getting-started.html">Build your first optimizer</a> puts these steps into a complete run. <a href="/guide/fundamentals/problems.html">Problems</a> then walks through the parts. The <a href="/reference/glossary.html">glossary</a> defines the terms.</p>`,33)])}var d=n(l,[[`render`,u]]);export{c as __pageData,d as default};